      code: `DECLARE @start DATETIME = '2026-10-31 06:00', @end DATETIME = '2026-11-07 06:00';

WITH r AS (
    SELECT f.machine, f.fault, COUNT(*) AS events,
        CAST(SUM(d.secs) / 60.0 AS DECIMAL(8,2)) AS minutes
    FROM fault_log AS f
    CROSS APPLY (SELECT DATEDIFF(SECOND, f.start_ts, f.end_ts) AS secs) AS d
    WHERE f.start_ts >= @start AND f.start_ts < @end
    GROUP BY f.machine, f.fault
    HAVING COUNT(*) >= 3
)
SELECT r.machine, r.fault, r.events, r.minutes,
    (SELECT COUNT(*) FROM work_order AS w
     WHERE w.machine = r.machine AND w.failure_mode = r.fault
         AND w.wo_type IN ('PM', 'Improvement')) AS preventive_orders
FROM r
ORDER BY r.minutes DESC;`,
      about: "A failure that keeps coming back needs prevention, not another repair. Hoop Driver 1's misfeeds happened 11 times for 61.23 minutes, and nothing preventive targets them: only repairs, and a sensor rebuild still open. Char flares have a monthly PM and an open calibration against them. The correlated subquery counts, for each repeat, the preventive orders aimed at it. The E-stops are operator safety actions rather than failures, so no PM belongs there; check why they were pressed. The work orders, hours and their dates are illustrative; the faults are the canonical fault_log.",
